from django.db import migrations, models

# Marcadores de texto que só podem ter vindo do cabeçalho de uma exportação.
# Em 19/10/2026 dois valores entraram assim no campo de consulta registrada:
# o do Espacenet ("N results found for ...") e o do Google ("search URL:,https://...").
MARCADORES = ("results found for", "https://patents.google.com/")


def para_no_arquivo(apps, schema_editor):
    """Move para o campo de evidência o que foi lido do arquivo, e limpa a declarada."""
    SourceFile = apps.get_model("studies", "SourceFile")
    for sf in SourceFile.objects.exclude(query_text=""):
        t = (sf.query_text or "").strip()
        if any(m.lower() in t.lower() for m in MARCADORES):
            sf.query_no_arquivo = t
            sf.query_text = ""
            sf.save(update_fields=["query_no_arquivo", "query_text"])


def para_declarada(apps, schema_editor):
    """Reversão: devolve a evidência ao campo de consulta (como estava antes)."""
    SourceFile = apps.get_model("studies", "SourceFile")
    for sf in SourceFile.objects.exclude(query_no_arquivo="").filter(query_text=""):
        sf.query_text = sf.query_no_arquivo
        sf.save(update_fields=["query_text"])



